//! The bindings of `protocols/bardo-window-v1.xml`, generated by wayland-scanner's macros the way
//! wayland-protocols generates its own. The XML names `xdg_toplevel`, so its interfaces and types
//! are imported from wayland-protocols' xdg-shell.
#![allow(
    dead_code,
    non_camel_case_types,
    unused_unsafe,
    unused_variables,
    non_upper_case_globals,
    non_snake_case,
    unused_imports,
    missing_docs,
    clippy::all,
    reason = "wayland-scanner generated bindings, which follow the protocol XML's names and macro output"
)]

pub(super) mod client {
    //! Client-side API of the protocol.
    use wayland_client;
    use wayland_client::protocol::wl_region;
    use wayland_protocols::xdg::shell::client::xdg_toplevel;

    pub mod __interfaces {
        use wayland_client::protocol::__interfaces::{WL_REGION_INTERFACE, wl_region_interface};
        use wayland_protocols::xdg::shell::client::__interfaces::{
            XDG_TOPLEVEL_INTERFACE, xdg_toplevel_interface,
        };
        wayland_scanner::generate_interfaces!("protocols/bardo-window-v1.xml");
    }
    use self::__interfaces::{BARDO_WINDOW_MANAGER_V1_INTERFACE, BARDO_WINDOW_V1_INTERFACE};

    wayland_scanner::generate_client_code!("protocols/bardo-window-v1.xml");
}

/// The server side, for the fake compositor the tests talk to.
#[cfg(test)]
pub(super) mod server {
    use wayland_protocols::xdg::shell::server::*;
    use wayland_server;
    use wayland_server::protocol::*;

    pub mod __interfaces {
        use wayland_protocols::xdg::shell::server::__interfaces::*;
        use wayland_server::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/bardo-window-v1.xml");
    }
    use self::__interfaces::*;

    wayland_scanner::generate_server_code!("protocols/bardo-window-v1.xml");
}
